import{_ as t,o,c as n,a3 as a}from"./chunks/framework.cNy3aYYk.js";const m=JSON.parse('{"title":"Companies — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Companies — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/companies"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Companies — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/companies"}]]},"headers":[],"relativePath":"user-guide/companies.md","filePath":"user-guide/companies.md","lastUpdated":1791556751000}'),s={name:"user-guide/companies.md"};function r(i,e,l,d,c,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="companies-—-user-guide" tabindex="-1">Companies — User Guide <a class="header-anchor" href="#companies-—-user-guide" aria-label="Permalink to &quot;Companies — User Guide&quot;">​</a></h1><h2 id="who-can-use-companies" tabindex="-1">Who can use Companies <a class="header-anchor" href="#who-can-use-companies" aria-label="Permalink to &quot;Who can use Companies&quot;">​</a></h2><p>Your workspace must have the <strong>Companies</strong> module installed. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>export</code>, <code>import</code> as needed).</p><p>Without <strong>assign</strong>, you only see companies assigned to you.</p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Companies</strong> from the sidebar under <strong>CRM</strong> (between Leads and Contacts).</p><ul><li>Search by name, email, phone, website, or industry</li><li>Filter by industry and assignee, or toggle <strong>My Companies</strong></li><li>KPI cards summarize total companies, my companies, unassigned, with email, and created this week</li><li>The table shows the <strong>latest note</strong>; hover a truncated preview to read the full note</li><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted company from the row menu</li><li><strong>Delete permanently</strong> (force delete) requires <code>companies.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New company</strong></li><li>Enter name (required) and optional email, phone, website, industry, address, source, and assignee</li><li>Save</li></ol><p>Edit from the row menu or the record page.</p><h2 id="related-sales-documents" tabindex="-1">Related sales documents <a class="header-anchor" href="#related-sales-documents" aria-label="Permalink to &quot;Related sales documents&quot;">​</a></h2><p>On a company record page (when the matching module is installed and you have create permission), use <strong>New quotation</strong>, <strong>New invoice</strong>, or <strong>New payment</strong> — create opens with <code>?company=</code> preselected.</p><h2 id="billing-hub-statement" tabindex="-1">Billing hub &amp; statement <a class="header-anchor" href="#billing-hub-statement" aria-label="Permalink to &quot;Billing hub &amp; statement&quot;">​</a></h2><p>When <strong>Invoices</strong> and/or <strong>Payments</strong> are installed, the company record shows invoiced / paid / remaining totals, recent documents (including credit notes when installed), deep links to <code>/invoices?company=</code> and <code>/payments?company=</code>, and a <strong>Statement</strong> page with opening/closing balance for the selected date range (PDF when available).</p><h2 id="related-opportunities-tickets-projects-documents" tabindex="-1">Related opportunities, tickets, projects &amp; documents <a class="header-anchor" href="#related-opportunities-tickets-projects-documents" aria-label="Permalink to &quot;Related opportunities, tickets, projects &amp; documents&quot;">​</a></h2><p>When those modules are installed and you can view them, the company record also lists recent <strong>opportunities</strong>, <strong>help desk tickets</strong>, <strong>projects</strong>, and <strong>documents</strong> linked to this company. <strong>View all</strong> opens the module list filtered with <code>?company=</code>.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the record page or the create/edit form.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the company</li><li><strong>Activity</strong> — timeline of create, update, assignment, note, and delete/restore events</li></ul><h2 id="linking-contacts" tabindex="-1">Linking Contacts <a class="header-anchor" href="#linking-contacts" aria-label="Permalink to &quot;Linking Contacts&quot;">​</a></h2><p>On a Contact create/edit form, when Companies is installed and you have <code>companies.view</code>, pick a <strong>Company</strong> from the picker. Use <strong>New</strong> (requires <code>companies.create</code>) to create a company in a dialog without leaving the contact form — the new company is selected automatically. The contact’s legacy company text field is kept in sync with the linked Company’s name. The company record page lists linked contacts.</p><h2 id="follow-ups-1-4-0" tabindex="-1">Follow-ups (1.4.0) <a class="header-anchor" href="#follow-ups-1-4-0" aria-label="Permalink to &quot;Follow-ups (1.4.0)&quot;">​</a></h2><p>Open a company record page and use the <strong>Follow-ups</strong> section:</p><ol><li>Enter a <strong>Title</strong> and <strong>Due at</strong> (workspace <strong>Timezone</strong>, Settings → General), optional notes/assignee — requires <code>companies.update</code></li><li><strong>Create follow-up</strong> saves it as <strong>pending</strong>. The company&#39;s <strong>Next follow-up</strong> field (shown on the record header, table, and list sheet peek) always reflects the earliest pending follow-up</li><li><strong>Reschedule</strong> loads a follow-up back into the form so you can change its due date, title, or notes, then <strong>Save follow-up</strong></li><li><strong>Complete</strong> marks a follow-up done — it drops out of Next follow-up and no longer triggers due/overdue reminders</li></ol><p>When <strong>Calendar</strong> is installed, each company&#39;s next pending follow-up is projected onto the assignee&#39;s calendar as a 1-hour event (source <strong>Company</strong>); completing or clearing the last pending follow-up removes that projection automatically.</p><p><strong>Due / overdue reminders:</strong> the assignee (falling back to the company&#39;s assignee) gets an in-app notification when a follow-up&#39;s due date arrives or has passed, sent by the same daily <code>crm:send-due-notifications</code> job that runs Lead, Contact, Task, and Contract reminders — one notification per follow-up per day.</p><h2 id="import-1-4-0" tabindex="-1">Import (1.4.0) <a class="header-anchor" href="#import-1-4-0" aria-label="Permalink to &quot;Import (1.4.0)&quot;">​</a></h2><p>Users with <strong>import</strong> can bulk-load companies from <strong>CSV</strong> or <strong>XLSX</strong>:</p><ol><li>Open <strong>Import</strong> and download a sample template if needed (CSV or XLSX)</li><li>Upload a file (drag &amp; drop or browse)</li><li>Map spreadsheet columns to company fields (<strong>Name</strong> is required; Email, Phone, Website, Industry, Source, and Assigned To are optional)</li><li>Choose unique fields (<strong>Email</strong> / <strong>Phone</strong>) and duplicate behavior (<strong>Skip</strong>, <strong>Update existing</strong>, or <strong>Keep duplicate</strong>)</li><li>Preview counts and validation errors (nothing is written yet)</li><li>Start the import — it runs in the background; watch progress until complete</li></ol><p><strong>Update existing</strong> also requires the <strong>update</strong> permission. Like Contacts, Company import has <strong>no equal-distribute assignment mode</strong> — an <strong>Assigned To</strong> column (matched by user email) sets the assignee directly, or rows default the same way manual create does.</p><p>Use <strong>Import history</strong> to review past imports, download the original file, <strong>failed_records.csv</strong>, or <strong>error_report.csv</strong>.</p><h2 id="export-1-4-0" tabindex="-1">Export (1.4.0) <a class="header-anchor" href="#export-1-4-0" aria-label="Permalink to &quot;Export (1.4.0)&quot;">​</a></h2><p>Users with <strong>export</strong> can download the current filtered set as <strong>CSV</strong> or <strong>XLSX</strong>, including industry, assignee, creator, and next follow-up.</p>',34)])])}const h=t(s,[["render",r]]);export{m as __pageData,h as default};
